+import { CxError } from '../shared/errors.js';
+
+const RESERVED_SECTION_NAMES = new Set(['manifest', 'assets', 'bundle']);
+const VALID_STYLES = new Set<CxStyle>(['xml', 'markdown', 'json', 'plain']);
+const VALID_DEDUP_MODES = new Set<'fail' | 'first-wins'>(['fail', 'first-wins']);
+const VALID_UNMATCHED_MODES = new Set<'ignore' | 'fail'>(['ignore', 'fail']);
+const VALID_ASSET_MODES = new Set<'copy' | 'ignore' | 'fail'>(['copy', 'ignore', 'fail']);
+
+function expectString(value: unknown, label: string): string {
+  if (typeof value !== 'string' || value.length === 0) {
+    throw new CxError(`${label} must be a non-empty string.`);
+  }
+  return value;
+}
+
+function expectBoolean(value: unknown, label: string, defaultValue: boolean): boolean {
+  if (value === undefined) {
+    return defaultValue;
+  }
+
+  if (typeof value !== 'boolean') {
+    throw new CxError(`${label} must be a boolean.`);
+  }
+
+  return value;
+}
+
+function expectStringArray(value: unknown, label: string, defaultValue: string[] = []): string[] {
+  if (value === undefined) {
+    return [...defaultValue];
+  }
+
+  if (!Array.isArray(value) || value.some((entry) => typeof entry !== 'string' || entry.length === 0)) {
+    throw new CxError(`${label} must be an array of non-empty strings.`);
+  }
+
+  return [...value];
+}
+
+function expectEnum<T extends string>(
+  value: unknown,
+  label: string,
+  validValues: Set<T>,
+  defaultValue: T,
+): T {
+  if (value === undefined) {
+    return defaultValue;
+  }
+
+  if (typeof value !== 'string' || !validValues.has(value as T)) {
+    throw new CxError(`${label} must be one of: ${[...validValues].join(', ')}.`);
+  }
+
+  return value as T;
+}
+
+function normalizeSection(sectionName: string, input: Record<string, unknown> | undefined): CxSectionConfig {
+  if (!input) {
+    throw new CxError(`sections.${sectionName} must be a table.`);
+  }
+
+  const include = expectStringArray(input.include, `sections.${sectionName}.include`);
+  if (include.length === 0) {
+    throw new CxError(`sections.${sectionName}.include must contain at least one pattern.`);
+  }
+
+  const style = input.style === undefined
+    ? undefined
+    : expectEnum(input.style, `sections.${sectionName}.style`, VALID_STYLES, DEFAULT_CONFIG_VALUES.repomix.style);
+
+  const normalized: CxSectionConfig = {
+    include,
+    exclude: expectStringArray(input.exclude, `sections.${sectionName}.exclude`, []),
+  };
+
+  if (style !== undefined) {
+    normalized.style = style;
+  }
+
+  return normalized;
+}
+
+function resolveTemplate(value: string, projectName: string): string {
+  return value.replaceAll('{project}', projectName);
+}
+
+function ensureSafeProjectName(projectName: string): void {
+  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(projectName)) {
+    throw new CxError('project_name must be filesystem-safe and use only letters, numbers, dot, underscore, or hyphen.');
+  }
+}
+
+export async function loadCxConfig(configPath: string): Promise<CxConfig> {
+  const raw = await fs.readFile(configPath, 'utf8');
+  const parsed = parseToml(raw) as CxConfigInput;
+  const configDir = path.dirname(path.resolve(configPath));
+  const schemaVersion = parsed.schema_version;
+
+  if (schemaVersion !== 1) {
+    throw new CxError('schema_version must be 1.');
+  }
+
+  const projectName = expectString(parsed.project_name, 'project_name');
+  ensureSafeProjectName(projectName);
+
+  const sourceRoot = path.resolve(configDir, expectString(parsed.source_root, 'source_root'));
+  const outputDir = path.resolve(configDir, expectString(parsed.output_dir, 'output_dir'));
+  const repomix = parsed.repomix ?? {};
+  const files = parsed.files ?? {};
+  const dedup = parsed.dedup ?? {};
+  const manifest = parsed.manifest ?? {};
+  const checksums = parsed.checksums ?? {};
+  const assets = parsed.assets ?? {};
+  const sectionsInput = parsed.sections;
+
